package com.aoo.bcg.wordcard;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class YzchzRulesTest{@Test void portsHuXiTable(){assertEquals(6,YzchzRules.concealed(List.of(2101,2102,2103),false).huXi);assertEquals(3,YzchzRules.concealed(List.of(201,701,1001),false).huXi);assertEquals(12,YzchzRules.concealed(List.of(2101,2102,2103,2104),false).huXi);}@Test void portsRedBlackAndSizeMingTang(){assertTrue(YzchzRules.mingTang(List.of(101),false).contains(YzchzRules.MingTang.DIAN_HU));assertTrue(YzchzRules.mingTang(Collections.nCopies(18,2101),true).contains(YzchzRules.MingTang.SHI_BA_DA));}@Test void enforcesHuXiCapPiaoXingTunAndWangPenalty(){assertEquals(20,YzchzRules.settlement(30,4,3,8,20,0));assertThrows(IllegalArgumentException.class,()->YzchzRules.settlement(14,0,0,0,0,0));}}
